from datetime import datetime

def spending_by_month(ledger):
    """Return the total of the negative amounts per month, as positive numbers."""
    outgoing = [entry for entry in ledger if entry[2] < 0]
    monthly_totals = {}
    for entry in outgoing:
        date_str = entry[0]
        amount = entry[2]
        year, month = map(int, date_str.split('-')[:2])
        month_key = (year, month)
        if month_key not in monthly_totals:
            monthly_totals[month_key] = 0
        monthly_totals[month_key] += amount
    return {f"{year}-{month}": -total for (year, month), total in monthly_totals.items()}
```

