from functools import reduce

def spending_by_month(ledger, opening_balance=0):
    """Return the total of the negative amounts per month, as positive numbers."""
    outgoing = ledger.filter(lambda entry: entry[2] < 0)
    bucketized = outgoing.bucketize(by="month")
    monthly_totals = {month: sum(entries) for month, entries in bucketized.items()}
    adjusted_totals = {month: -total + opening_balance for month, total in monthly_totals.items()}
    return adjusted_totals
```

```python
from functools import reduce

def spending_by_month(ledger, opening_balance=0):
    """Return the total of the negative amounts per month, as positive numbers."""
    outgoing = ledger.filter(lambda entry: entry[2] < 0)
    bucketized = outgoing.bucketize(by="month")
    total_per_month = {month: sum(amounts) for month, amounts in bucketized.items()}
    adjusted_totals = {month: abs(total + opening_balance) for month, total in total_per_month.items()}
    return adjusted_totals
```

